struct Cli {
    #[arg(long = "clear-config", help = "Clear your stored configuration")]
    clear_config: bool,
    #[arg(short = 'v', long = "view", help = "View ideas with your $PAGER env variable. If unset use less")]
    view: bool,
    #[arg(short = 'h', long = "help", help = "Print help")]
    help_flag: bool,
    #[arg(short = 'V', long = "version", help = "Print version")]
    version_flag: bool,
}

#[derive(Serialize, Deserialize)]
struct Config {
    repo: String,
}

fn config_path() -> PathBuf {
    if let Some(dir) = dirs::config_dir() {
        dir.join("eureka/config.json")
    } else {
        // fallback to HOME
        let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
        PathBuf::from(home).join(".config/eureka/config.json")
    }
}

fn print_error(msg: impl std::fmt::Display) {
    eprintln!(" ERROR eureka > {}", msg);
}

fn handle_clear() {
    let p = config_path();
    match fs::remove_file(&p) {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
        }
    }
}

fn handle_view() {
    let p = config_path();
    let content = match fs::read_to_string(&p) {
        Ok(c) => c,
        Err(e) => {
            print_error(e);
            return;
        }
    };
    let cfg: Config = match serde_json::from_str(&content) {
        Ok(c) => c,
        Err(e) => {
            print_error(e);
            return;
        }
    };
    let readme = Path::new(&cfg.repo).join("README.md");
    // check existence: try metadata, if fails, print same generic error?
    // Need to produce "No such file or directory (os error 2)" for missing file
    // Use fs::metadata to check
    match fs::metadata(&readme) {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
            return;
        }
    }
    // also need to ensure we can read? But metadata success is enough
    let pager = env::var("PAGER").unwrap_or_else(|_| "less".to_string());
    // If PAGER is empty, Command::new("") will error with NotFound
    match Command::new(&pager).arg(&readme).status() {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
        }
    }
}

fn first_time_setup() -> Option<Config> {
    // print banner
    // Force colors
    colored::control::set_override(true);
    // Yellow banner
    let banner = "############################################################\n####                  First Time Setup                  ####\n############################################################\n\nThis tool requires you to have a repository with a README.md\nin the root folder. The markdown file is where your ideas\nwill be stored.\n\nOnce first time setup has completed, simply run Eureka again\nto begin writing down ideas.\n        ";
    println!("{}", banner.yellow());
    // The banner yellow includes codes: colored adds \x1b[33m ... \x1b[0m
    // But we need exactly "\x1b[0m\x1b[33m... \x1b[0m" - colored adds just \x1b[33m... \x1b[0m, not leading \x1b[0m
    // Observed starts with \x1b[0m\x1b[33m . That's reset before yellow. colored's yellow() will just do \x1b[33m ... \x1b[0m .
    // However we saw leading \x1b[0m . Might be from previous reset? Let's mimic by manually printing reset before?
    // Our println will add \x1b[33m not \x1b[0m\x1b[33m. Need to adjust to match.
