        print!("> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        let n = io::stdin().read_line(&mut input).unwrap();
        if n == 0 {
            // EOF: treat as empty and continue looping (will spin)
            continue;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        if !Path::new(trimmed).is_absolute() {
            println!("{}", "Path must be absolute".red());
            continue;
        }
        // create config
