fn config_path() -> PathBuf {
    if let Some(dir) = dirs::config_dir() {
        dir.join("eureka/config.json")
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
        PathBuf::from(home).join(".config/eureka/config.json")
    }
}

fn print_error(msg: impl std::fmt::Display) {
    eprintln!(" ERROR eureka > {}", msg);
}

fn handle_clear() {
    let p = config_path();
    match fs::remove_file(&p) {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
        }
    }
}

fn handle_view() {
    let p = config_path();
    let content = match fs::read_to_string(&p) {
        Ok(c) => c,
        Err(e) => {
            print_error(e);
            return;
        }
    };
    let cfg: Config = match serde_json::from_str(&content) {
        Ok(c) => c,
        Err(e) => {
            print_error(e);
            return;
        }
    };
    let readme = Path::new(&cfg.repo).join("README.md");
    match fs::metadata(&readme) {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
            return;
        }
    }
    let pager = env::var("PAGER").unwrap_or_else(|_| "less".to_string());
    match Command::new(&pager).arg(&readme).status() {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
        }
    }
