    let p = config_path();
    match fs::remove_file(&p) {
        Ok(_) => {},
        Err(e) => {
            print_error(e);
        }
    }
}

fn handle_view() {
    let p = config_path();
    let content = match fs::read_to_string(&p) {
        Ok(c) => c,
