    let banner = "############################################################\n####                  First Time Setup                  ####\n############################################################\n\nThis tool requires you to have a repository with a README.md\nin the root folder. The markdown file is where your ideas\nwill be stored.\n\nOnce first time setup has completed, simply run Eureka again\nto begin writing down ideas.\n        ";
    print!("\x1b[0m{}", banner.yellow());
    println!("\x1b[0m");
    loop {
        print!("\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\x1b[0m\n");
        print!("\x1b[0m> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        let n = io::stdin().read_line(&mut input).unwrap();
        if n == 0 {
            continue;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        if !Path::new(trimmed).is_absolute() {
            println!("\x1b[0m\x1b[31mPath must be absolute\x1b[0m");
            continue;
        }
        let cfg_path = config_path();
        if let Some(parent) = cfg_path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let cfg = Config { repo: trimmed.to_string() };
        let json = serde_json::to_string(&cfg).unwrap();
        let _ = fs::write(&cfg_path, json);
        println!("First time setup complete. Happy ideation!");
        return;
    }
}

fn get_editor() -> Result<String, String> {
    match env::var("EDITOR") {
        Ok(ed) => {
            if ed.is_empty() {
                // empty should be treated as attempting to execute empty, which will error later with No such file, but we return Ok("")
                return Ok(ed);
            }
            Ok(ed)
        },
        Err(_) => {
            if let Ok(path) = env::var("PATH") {
                for dir in path.split(':') {
                    let candidate = Path::new(dir).join("vi");
                    if candidate.exists() {
                        return Ok(candidate.to_string_lossy().to_string());
                    }
                }
            }
            Err("cannot find binary path".to_string())
        }
    }
}

fn handle_idea(cfg: Config) {
    colored::control::set_override(true);
    let summary = loop {
        print!("\x1b[0m\x1b[1m\x1b[32m>> Idea summary\x1b[0m\n");
        print!("\x1b[0m> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        let n = io::stdin().read_line(&mut input).unwrap();
        if n == 0 {
            continue;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        break trimmed.to_string();
    };

    let repo_path_str = cfg.repo.clone();
    let repo_path = Path::new(&repo_path_str);

    if repo_path_str.is_empty() {
        print_error(format!("failed to resolve path '': No such file or directory; class=Os (2); code=NotFound (-3)"));
        return;
    }

    let repo = match Repository::open(repo_path) {
        Ok(r) => r,
        Err(e) => {
            print_error(e);
            return;
        }
    };

    let readme_path = repo_path.join("README.md");
    let mut editor_error: Option<String> = None;
    let readme_exists = readme_path.exists();
    if readme_exists {
        match get_editor() {
            Ok(ed) => {
                // Check if ed is empty? Command::new("") will error with NotFound
                let res = Command::new(&ed).arg(&readme_path).status();
                if let Err(e) = res {
                    editor_error = Some(e.to_string());
                    // normalize error message for empty editor? The error from Command::new("") is "No such file or directory (os error 2)"
                    // That matches observed for empty EDITOR.
