        // Let's keep skip for now and see.
    }

    println!("Adding and committing your new idea to main..");

    let main_branch_exists = repo.find_branch("main", BranchType::Local).is_ok();

    let checkout_result: Result<(), git2::Error> = (|| {
        if main_branch_exists {
            let branch = repo.find_branch("main", BranchType::Local)?;
            let reference = branch.into_reference();
            let obj = reference.peel(ObjectType::Tree)?;
            let mut opts = git2::build::CheckoutBuilder::new();
            repo.checkout_tree(&obj, Some(&mut opts))?;
            repo.set_head(reference.name().unwrap())?;
        } else {
            let head = repo.head()?;
            let commit = head.peel_to_commit()?;
            repo.branch("main", &commit, false)?;
            let branch = repo.find_branch("main", BranchType::Local)?;
            let reference = branch.into_reference();
            let obj = reference.peel(ObjectType::Tree)?;
            let mut opts = git2::build::CheckoutBuilder::new();
            repo.checkout_tree(&obj, Some(&mut opts))?;
            repo.set_head(reference.name().unwrap())?;
        }
        Ok(())
    })();

    if let Err(e) = checkout_result {
        if let Some(ed_err) = editor_error {
            print_error(ed_err);
            return;
        } else {
            print_error(e);
            return;
        }
    }

    let commit_result: Result<(), git2::Error> = (|| {
        let mut index = repo.index()?;
        // Check README existence again for add_path - this will produce No such file if missing
        index.add_path(Path::new("README.md"))?;
