    // Exact: \x1b[0m\x1b[33m + banner + \n\x1b[0m
    // But banner already contains its own trailing spaces "        " then we need "\n\x1b[0m"
    // So do: print!("\x1b[0m\x1b[33m{}\n\x1b[0m", banner);
    // However banner already doesn't have trailing newline; we add one.
    // Observed after banner text "        " there is "\n" then "\x1b[0m"
    // So this matches.
    print!("\x1b[0m\x1b[33m{}\n\x1b[0m", banner);
    // Now prompt: "\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> "
    // But need extra "\x1b[0m" before bold green? Observed after previous "\x1b[0m" we have "\x1b[0m\x1b[1m\x1b[32m"
    // So we need another "\x1b[0m"
    // Actually previous println already printed "\x1b[0m\n" then next print starts with "\x1b[0m\x1b[1m..."
    // Let's craft loop accordingly
    loop {
        print!("\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        let n = io::stdin().read_line(&mut input).unwrap();
        if n == 0 {
            continue;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        if !Path::new(trimmed).is_absolute() {
            println!("\x1b[0m\x1b[31mPath must be absolute\x1b[0m");
            continue;
        }
        let cfg_path = config_path();
        if let Some(parent) = cfg_path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let cfg = Config { repo: trimmed.to_string() };
        let json = serde_json::to_string(&cfg).unwrap();
        let _ = fs::write(&cfg_path, json);
        println!("First time setup complete. Happy ideation!");
        return;
    }
}

fn get_editor() -> Result<String, String> {
    match env::var("EDITOR") {
        Ok(ed) => {
            Ok(ed)
        },
        Err(_) => {
            if let Ok(path) = env::var("PATH") {
                for dir in path.split(':') {
                    let candidate = Path::new(dir).join("vi");
                    if candidate.exists() {
                        return Ok(candidate.to_string_lossy().to_string());
                    }
                }
            }
            Err("cannot find binary path".to_string())
        }
    }
}

fn handle_idea(cfg: Config) {
    let summary = loop {
        print!("\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        let n = io::stdin().read_line(&mut input).unwrap();
        if n == 0 {
            continue;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        break trimmed.to_string();
    };

    let repo_path_str = cfg.repo.clone();
    let repo_path = Path::new(&repo_path_str);

    if repo_path_str.is_empty() {
        print_error(format!("failed to resolve path '': No such file or directory; class=Os (2); code=NotFound (-3)"));
        return;
    }

    let repo = match Repository::open(repo_path) {
        Ok(r) => r,
        Err(e) => {
            print_error(e);
            return;
        }
    };

    let readme_path = repo_path.join("README.md");
    let mut editor_error: Option<String> = None;
    let readme_exists = readme_path.exists();
    if readme_exists {
        match get_editor() {
            Ok(ed) => {
                let res = Command::new(&ed).arg(&readme_path).status();
                if let Err(e) = res {
                    editor_error = Some(e.to_string());
                }
            },
            Err(e) => {
                editor_error = Some(e);
            }
        }
    }

    println!("Adding and committing your new idea to main..");

    let main_branch_exists = repo.find_branch("main", BranchType::Local).is_ok();

    let checkout_result: Result<(), git2::Error> = (|| {
        if main_branch_exists {
            let branch = repo.find_branch("main", BranchType::Local)?;
            let reference = branch.into_reference();
            let obj = reference.peel(ObjectType::Tree)?;
            let mut opts = git2::build::CheckoutBuilder::new();
            repo.checkout_tree(&obj, Some(&mut opts))?;
            repo.set_head(reference.name().unwrap())?;
        } else {
            let head = repo.head()?;
            let commit = head.peel_to_commit()?;
            repo.branch("main", &commit, false)?;
            let branch = repo.find_branch("main", BranchType::Local)?;
            let reference = branch.into_reference();
            let obj = reference.peel(ObjectType::Tree)?;
            let mut opts = git2::build::CheckoutBuilder::new();
            repo.checkout_tree(&obj, Some(&mut opts))?;
            repo.set_head(reference.name().unwrap())?;
        }
        Ok(())
    })();

    if let Err(e) = checkout_result {
        if let Some(ed_err) = editor_error {
            print_error(ed_err);
            return;
        } else {
            print_error(e);
            return;
        }
    }

    let commit_result: Result<(), git2::Error> = (|| {
        let mut index = repo.index()?;
        index.add_path(Path::new("README.md"))?;
        index.write()?;
        let oid = index.write_tree()?;
        let tree = repo.find_tree(oid)?;
        let sig = repo.signature()?;
        let parent = repo.head()?.peel_to_commit()?;
        repo.commit(Some("HEAD"), &sig, &sig, &summary, &tree, &[&parent])?;
        Ok(())
    })();

    if let Err(e) = commit_result {
        if let Some(ed_err) = editor_error {
            print_error(ed_err);
            return;
        } else {
            let msg = e.to_string();
            if msg.contains("No such file") {
                print_error(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
            } else {
                print_error(e);
            }
            return;
        }
    }

    println!("Added and committed!");
    println!("Pushing your new idea..");

    let push_result: Result<(), git2::Error> = (|| {
        let mut remote = repo.find_remote("origin")?;
        remote.push(&["refs/heads/main"], None)?;
        Ok(())
    })();

    match push_result {
        Ok(_) => {
            println!("Pushed!");
            if let Some(ed_err) = editor_error {
                print_error(ed_err);
            }
        },
        Err(e) => {
            if let Some(ed_err) = editor_error {
                print_error(ed_err);
            } else {
                print_error(e);
            }
        }
    }
}

fn main() {
    let cli = Cli::parse();

    if cli.help_flag {
        println!("Input and store your ideas without leaving the terminal\n");
        println!("Usage: executable [OPTIONS]\n");
        println!("Options:");
        println!("      --clear-config  Clear your stored configuration");
        println!("  -v, --view          View ideas with your $PAGER env variable. If unset use less");
        println!("  -h, --help          Print help");
        println!("  -V, --version       Print version");
        return;
    }
    if cli.version_flag {
        println!("eureka 2.0.0");
        return;
    }

    if cli.clear_config {
        handle_clear();
        return;
    }
    if cli.view {
        handle_view();
        return;
    }

    let cfg_path = config_path();
    let cfg_opt: Option<Config> = match fs::read_to_string(&cfg_path) {
        Ok(content) => match serde_json::from_str(&content) {
            Ok(c) => Some(c),
            Err(_) => None,
        },
        Err(_) => None,
    };

    match cfg_opt {
        Some(cfg) => {
            handle_idea(cfg);
        },
        None => {
            first_time_setup();
        }
    }
}
